function maxProduct(nums) {
    let res = Math.max(...nums);
    let curMin = 1, curMax = 1;
    for (const n of nums) {
        if (n === 0) {
            curMin = 1;
            curMax = 1;
            continue;
        }
        const tmp = curMax * n;
        curMax = Math.max(n * curMax, n * curMin, n);
        curMin = Math.min(tmp, n * curMin, n);
        res = Math.max(res, curMax);
    }
    return res;
}
